import java.util.Scanner;

public class Main {
    static String s;
    static String qq = "QAQ";
    static int[][] arr;

    static int Q(int m, int n) {
        if (arr[n][m] != -1)
            return arr[n][m];
        if (m == 0)
            return 1;
        if (n == 0)
            return 0;
        int i = 0, j = 0;
        if (qq.charAt(m - 1) == s.charAt(n - 1))
            i = Q(m - 1, n - 1);
        j = Q(m, n - 1);
        arr[n][m] = i + j;
        return i + j;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        s = scanner.nextLine();
        arr = new int[s.length() + 1][4];
        for (int i = 0; i < s.length() + 1; i++) {
            for (int j = 0; j < 4; j++)
                arr[i][j] = -1;
        }
        System.out.println(Q(3, s.length()));
    }
}

